package pilot

import java.io.IOException
import java.util.UUID
import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.api.Assertions.assertThrows
import org.junit.jupiter.api.Test

// Шлюз по контракту: атомарная дедупликация по ключу; первые lostResponses ответов теряются после списания.
class DedupGateway(private val balanceCents: Long = Long.MAX_VALUE, private val lostResponses: Int = 0) : PaymentGateway {
    val keys = mutableListOf<String>()
    private val receiptsByKey = mutableMapOf<String, Receipt>()
    var debitedCents = 0L
        private set

    override fun charge(request: Charge, idempotencyKey: String): Receipt {
        keys += idempotencyKey
        val receipt = receiptsByKey[idempotencyKey] ?: run {
            if (debitedCents + request.cents > balanceCents) throw RejectedCharge()
            debitedCents += request.cents
            Receipt("r${receiptsByKey.size + 1}").also { receiptsByKey[idempotencyKey] = it }
        }
        if (keys.size <= lostResponses) throw IOException("response lost after debit")
        return receipt
    }
}

class PaymentServiceReviewTest {
    private val request = Charge("acc-1", 100)

    private fun service(gateway: PaymentGateway) = PaymentService(gateway) { UUID.randomUUID().toString() }

    @Test
    fun `one charge call debits once when the first response is lost after the debit`() {
        val gateway = DedupGateway(lostResponses = 1)

        val receipt = service(gateway).charge(request)

        assertEquals(100, gateway.debitedCents, "keys=${gateway.keys}")
        assertEquals(Receipt("r1"), receipt)
    }

    @Test
    fun `all attempts of one charge call use the same idempotency key`() {
        val gateway = DedupGateway(lostResponses = 2)

        service(gateway).charge(request)

        assertEquals(3, gateway.keys.size)
        assertEquals(1, gateway.keys.toSet().size, "keys=${gateway.keys}")
    }

    @Test
    fun `charge returns the receipt instead of a rejection when the lost first attempt already debited`() {
        val gateway = DedupGateway(balanceCents = 100, lostResponses = 1)

        val receipt = service(gateway).charge(request)

        assertEquals(Receipt("r1"), receipt)
        assertEquals(100, gateway.debitedCents)
    }

    @Test
    fun `three lost responses debit once and rethrow IOException`() {
        val gateway = DedupGateway(lostResponses = 3)

        assertThrows(IOException::class.java) { service(gateway).charge(request) }

        assertEquals(3, gateway.keys.size)
        assertEquals(100, gateway.debitedCents, "keys=${gateway.keys}")
    }

    @Test
    fun `rejected charge is not retried`() {
        var calls = 0
        val gateway = PaymentGateway { _, _ -> calls++; throw RejectedCharge() }

        assertThrows(RejectedCharge::class.java) { service(gateway).charge(request) }

        assertEquals(1, calls)
    }

    @Test
    fun `rejection on a retry stops further attempts`() {
        var calls = 0
        val gateway = PaymentGateway { _, _ -> if (++calls == 1) throw IOException("refused") else throw RejectedCharge() }

        assertThrows(RejectedCharge::class.java) { service(gateway).charge(request) }

        assertEquals(2, calls)
    }

    @Test
    fun `IOException is attempted at most three times`() {
        var calls = 0
        val gateway = PaymentGateway { _, _ -> calls++; throw IOException("down") }

        assertThrows(IOException::class.java) { service(gateway).charge(request) }

        assertEquals(3, calls)
    }

    @Test
    fun `separate charge calls with equal data are separate payments`() {
        val gateway = DedupGateway()
        val service = service(gateway)

        val first = service.charge(request)
        val second = service.charge(request)

        assertEquals(200, gateway.debitedCents)
        assertEquals(listOf(Receipt("r1"), Receipt("r2")), listOf(first, second))
    }
}
